package com.vibecode.roadmap.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="roadmap_phases") public class RoadmapPhaseRecord { @Id private UUID id; @Column(name="roadmap_id",nullable=false) private UUID roadmapId; @Column(nullable=false) private int position; @Column(nullable=false) private String title; private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private PhaseStatus status; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected RoadmapPhaseRecord(){} public RoadmapPhaseRecord(UUID roadmapId,int position,String title,String description){id=UUID.randomUUID();this.roadmapId=roadmapId;this.position=position;this.title=title;this.description=description;status=PhaseStatus.PLANNED;createdAt=updatedAt=Instant.now();} public UUID id(){return id;} public UUID roadmapId(){return roadmapId;} public int position(){return position;} public String title(){return title;} public String description(){return description;} public PhaseStatus status(){return status;} public void status(PhaseStatus value){status=value;updatedAt=Instant.now();}}
